274	/* ---- fetch override --------------------------------------------------- */
275	const COLLECTION_HINT = /(tenants|transactions|invoices|schedules|stones|items|payments|merchants|keys|events|leads)(\/?$|\?)/;
276	
277	function jsonResponse(body: unknown, status = 200): Response {
278	  return new Response(JSON.stringify(body), {
279	    status,
280	    headers: { 'Content-Type': 'application/json' },
281	  });
282	}
