284	export function installMockApi() {
285	  // Seed an authenticated session.
286	  const token = fakeJwt();
287	  localStorage.setItem('authToken', token);
288	  localStorage.setItem('merchantId', String(MERCHANT_ID));
289	  localStorage.setItem('user', JSON.stringify({ id: 1, merchantId: MERCHANT_ID, role: 'merchant', email: MERCHANT.email }));
290	
291	  const realFetch = window.fetch.bind(window);
292	
293	  window.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
294	    const rawUrl = typeof input === 'string' ? input : input instanceof URL ? input.href : (input as Request).url;
295	    const method = (init?.method || (input instanceof Request ? input.method : 'GET')).toUpperCase();
296	
297	    // Only intercept our own API. Everything else (chunks, images, sw.js) is real.
298	    if (!/\/api\//.test(rawUrl)) return realFetch(input as any, init);
299	
300	    let url: URL;
301	    try { url = new URL(rawUrl, window.location.origin); } catch { return jsonResponse({}); }
302	    const path = url.pathname + url.search;
303	
304	    // Binary / download endpoints we don't mock — let them fail quietly (no data).
305	    if (/(qr|receipt-pdf|export|logo|vapid-key|\.pdf|\.csv|\.png)/.test(path)) {
306	      return jsonResponse({}, 200);
307	    }
308	
309	    // Mutations: acknowledge success so optimistic UI settles.
310	    if (method !== 'GET') return jsonResponse({ success: true, id: Date.now() });
311	
312	    for (const r of ROUTES) {
313	      const m = path.match(r.re);
314	      if (m) return jsonResponse(r.data(m, url, init));
315	    }
316	
317	    // Unknown GET: sensible default so nothing crashes.
318	    return jsonResponse(COLLECTION_HINT.test(path) ? [] : {});
319	  };
320	
321	  // Boot straight into the app instead of the marketing landing page.
322	  if (window.location.pathname === '/' || window.location.pathname === '') {
323	    window.history.replaceState(null, '', '/dashboard');
324	  }
325	
326	  // eslint-disable-next-line no-console
327	  console.info('[mock-api] Demo mode active — all /api calls are served with canned data.');
328	}
