  id: i + 1,
  merchantId: MERCHANT_ID,
  firstName,
  lastName,
  email: `${firstName.toLowerCase()}.${lastName.toLowerCase()}@example.co.nz`,
  phone: `+64 21 ${300 + i}${400 + i}${500 + i}`,
  siteAddress,
  preferredChannel: i % 2 === 0 ? 'email' : 'sms',
  status: 'active',
  notes,
  archivedAt: null,
  createdAt: iso(now - (150 - i * 14) * DAY),
  updatedAt: iso(now - (i + 1) * DAY),
}));

function buildTradeInvoices() {
  const invs: any[] = [];
  let id = 7000;
  TRADE_CLIENTS.forEach((c, ci) => {
    const jobValue = 1800 + ci * 650; // dollars per job
    for (let m = 3; m >= 0; m--) {
      const created = now - m * 26 * DAY;
      const due = created + 14 * DAY;
      let status: string;
      let paidAt: string | null = null;
      if (m === 0) {
        const roll = seeded(id);
        if (roll > 0.4) { status = 'paid'; paidAt = iso(now - Math.floor(seeded(id * 2) * 6) * DAY); }
        else if (roll > 0.2) { status = 'sent'; }
        else { status = 'overdue'; }
      } else {
        status = 'paid';
        paidAt = iso(due - 2 * DAY);
      }
      invs.push({
        id,
        merchantId: MERCHANT_ID,
        clientProfileId: c.id,
        siteAddress: c.siteAddress,
        amountCents: jobValue * 100,
        token: `job_${id}`,
        kind: 'job',
        chargeType: 'job',
        description: `${c.notes} — invoice #${id}`,
        status,
        dueAt: iso(due),
        sentAt: iso(created),
        paidAt,
        voidedAt: null,
        reminderCount: status === 'overdue' ? 2 : status === 'sent' ? 1 : 0,
        splitEnabled: false,
        splitPaidCount: 0,
        deliveryChannel: c.preferredChannel,
        createdAt: iso(created),
        updatedAt: iso(created),
      });
      id++;
    }
  });
  return invs.sort((a, b) => +new Date(b.createdAt) - +new Date(a.createdAt));
}
