  clientProfileId: c.id,
  siteAddress: c.siteAddress,
  token: `quote_${8000 + i}`,
  amountCents: (2400 + i * 900) * 100,
  status: ['sent', 'accepted', 'draft'][i],
  description: `Quote — ${c.notes}`,
  validUntil: iso(now + (14 - i * 3) * DAY),
  createdAt: iso(now - (i + 2) * DAY),
  updatedAt: iso(now - (i + 1) * DAY),
}));

