  isSplit: false,
  splitEnabled: false,
  totalSplits: 1,
  completedSplits: 1,
  createdAt: iso(now),
};

// Resolve a checkout token to the invoice-shape the checkout page expects.
// Falls back to a fresh payable rent invoice so any demo link is payable.
function resolveInvoice(rawToken: string) {
  const inv = [...INVOICES, ...TRADE_INVOICES].find((i: any) => i.token === rawToken);
  if (inv) {
    const isTrade = String(inv.token).startsWith('job_');
    return {
      invoiceId: inv.id,
      merchantId: MERCHANT_ID,
      amountCents: inv.amountCents,
      kind: inv.kind ?? (isTrade ? 'job' : 'rent'),
      description: inv.description,
      vertical: isTrade ? 'trades' : 'property',
      alreadyPaid: inv.status === 'paid' || inv.status === 'paid_external',
      splitEnabled: false,
      splitCount: 0,
      splitPaidCount: 0,
    };
  }
  return {
