import http from 'http';
import { readFile, stat } from 'fs/promises';
import { join, extname } from 'path';
const ROOT = process.argv[2];
const PORT = 4455;
const MIME = { '.html':'text/html', '.js':'text/javascript', '.css':'text/css', '.json':'application/json', '.svg':'image/svg+xml', '.png':'image/png', '.woff2':'font/woff2', '.ico':'image/x-icon' };
const server = http.createServer(async (req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]);
  let fp = join(ROOT, p);
  try {
    const s = await stat(fp);
    if (s.isDirectory()) fp = join(fp, 'index.html');
  } catch {
    // SPA fallback: unknown non-asset path -> index.html
    if (!extname(p)) fp = join(ROOT, 'index.html');
  }
  try {
    const buf = await readFile(fp);
    res.writeHead(200, { 'Content-Type': MIME[extname(fp)] || 'application/octet-stream' });
    res.end(buf);
  } catch {
    res.writeHead(404); res.end('nf');
  }
});
server.listen(PORT, () => console.log('serving', ROOT, 'on', PORT));
EOF
