import { chromium } from 'playwright';
const BASE = 'http://localhost:4455';

const ROUTES = [
  ['/dashboard', 'retail dashboard'],
  ['/stock', 'retail stock'],
  ['/transactions', 'retail transactions'],
  ['/settings', 'settings'],
  ['/terminal', 'retail terminal'],
  ['/property', 'property dashboard'],
  ['/property/tenants', 'tenant directory'],
  ['/property/tenants/1', 'tenant profile'],
  ['/property/analytics', 'property analytics'],
  ['/property/terminal', 'property terminal'],
  ['/trades', 'trades dashboard'],
  ['/trades/clients', 'trades clients'],
  ['/trades/clients/1', 'trades client profile'],
  ['/trades/analytics', 'trades analytics'],
  ['/trades/terminal', 'trades terminal'],
];

const browser = await chromium.launch();
const results = [];
for (const [route, label] of ROUTES) {
  const ctx = await browser.newContext({ viewport: { width: 420, height: 900 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  try {
    await page.goto(BASE + route, { waitUntil: 'networkidle', timeout: 20000 });
    await page.waitForTimeout(1200);
    const bodyLen = (await page.textContent('body') || '').replace(/\s+/g, ' ').trim().length;
    const realErrors = errors.filter(e => !/sw\.js|ServiceWorker|Failed to load resource|favicon|manifest|net::ERR|pay\.google|apple|windcave/i.test(e));
    results.push({ route, label, bodyLen, errCount: realErrors.length, err: realErrors[0] || '' });
  } catch (e) {
    results.push({ route, label, bodyLen: 0, errCount: 99, err: 'NAV FAIL: ' + e.message });
  }
  await ctx.close();
}

// Checkout pay flow: retail transaction
async function payFlow(url, name) {
  const ctx = await browser.newContext({ viewport: { width: 420, height: 900 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  try {
    await page.goto(BASE + url, { waitUntil: 'networkidle', timeout: 20000 });
    await page.waitForTimeout(1000);
    // open card form: click element containing "card" text
    const cardToggle = page.locator('text=/pay by card|card/i').first();
    if (await cardToggle.count()) { await cardToggle.click().catch(()=>{}); }
    await page.waitForTimeout(700);
    // click the Pay button
    const payBtn = page.locator('button', { hasText: /^Pay / }).first();
    const hasPay = await payBtn.count();
    if (hasPay) await payBtn.click().catch(()=>{});
    await page.waitForTimeout(1600);
    const txt = (await page.textContent('body') || '');
    const ok = /Payment Successful|Thank you/i.test(txt);
    return { name, url, hadPayBtn: !!hasPay, success: ok, err: errors[0] || '' };
  } catch (e) {
    return { name, url, hadPayBtn: false, success: false, err: 'NAV FAIL: ' + e.message };
  } finally { await ctx.close(); }
}

const pay1 = await payFlow('/checkout/90210', 'retail checkout pay');
const pay2 = await payFlow('/r/inv_5000', 'property invoice pay');
const pay3 = await payFlow('/pay/1', 'customer-payment -> checkout');

console.log('\n=== PAGE RENDER RESULTS ===');
for (const r of results) {
  const flag = r.errCount > 0 ? 'ERR' : (r.bodyLen < 40 ? 'THIN' : 'ok');
  console.log(`[${flag}] ${r.route.padEnd(24)} len=${String(r.bodyLen).padEnd(6)} ${r.err ? ':: ' + r.err.slice(0,120) : ''}`);
}
console.log('\n=== CHECKOUT PAY FLOWS ===');
for (const p of [pay1, pay2, pay3]) {
  console.log(`[${p.success ? 'PAID' : 'FAIL'}] ${p.name.padEnd(30)} payBtn=${p.hadPayBtn} ${p.err ? ':: ' + p.err.slice(0,120) : ''}`);
}
await browser.close();

